import{_ as l,C as u,o as n,c as r,a3 as e,b as s,w as i,a as o,E as k,a4 as p}from"./chunks/framework.BvvarXmc.js";const m="/screenshots/kantin-settlements.png",P=JSON.parse('{"title":"Tutup Buku & Settlement Supplier","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-kantin/tutup-buku.md","filePath":"panduan-kantin/tutup-buku.md","lastUpdated":null}'),d={name:"panduan-kantin/tutup-buku.md"};function g(h,a,b,c,T,S){const t=u("Mermaid");return n(),r("div",null,[a[1]||(a[1]=e('<h1 id="tutup-buku-settlement-supplier" tabindex="-1">Tutup Buku &amp; Settlement Supplier <a class="header-anchor" href="#tutup-buku-settlement-supplier" aria-label="Permalink to &quot;Tutup Buku &amp; Settlement Supplier&quot;">​</a></h1><p>Fitur <strong>Tutup Buku &amp; Settlement Supplier</strong> adalah modul akuntansi kasir kantin yang mengelola rekonsiliasi penjualan harian, pembagian komisi kantin sekolah, serta pencairan pembayaran bagi pedagang luar yang menitipkan makanannya di kantin (sistem konsinyasi).</p><p>Fitur ini dapat diakses oleh Administrator dan Pengelola Kantin melalui menu <strong>Kantin</strong> &gt; <strong>Tutup Buku &amp; Settlement</strong> pada sidebar aplikasi.</p><hr><h2 id="tampilan-halaman-tutup-buku-settlement" tabindex="-1">Tampilan Halaman Tutup Buku &amp; Settlement <a class="header-anchor" href="#tampilan-halaman-tutup-buku-settlement" aria-label="Permalink to &quot;Tampilan Halaman Tutup Buku &amp; Settlement&quot;">​</a></h2><p>Berikut adalah tampilan antarmuka manajemen tutup buku dan rekonsiliasi bagi hasil:</p><p><img src="'+m+'" alt="Tutup Buku &amp; Settlement Kantin"></p><hr><h2 id="_3-metrik-keuangan-utama" tabindex="-1">3 Metrik Keuangan Utama <a class="header-anchor" href="#_3-metrik-keuangan-utama" aria-label="Permalink to &quot;3 Metrik Keuangan Utama&quot;">​</a></h2><p>Di bagian atas halaman, sistem menyajikan tiga indikator keuangan krusial:</p><ol><li><strong>Total Omset Ter-settle (Total Sales)</strong>: Total nilai kotor seluruh penjualan barang konsinyasi pada periode tutup buku yang dipilih.</li><li><strong>Total Komisi Kantin (Canteen Commission)</strong>: Pendapatan bersih yang menjadi hak kas sekolah atau pengelola kantin (misal: 10% dari setiap makanan yang laku terjual).</li><li><strong>Total Payout Supplier (Supplier Payout)</strong>: Uang bersih yang wajib dicairkan atau diserahkan kepada para pedagang titipan mitra kantin.</li></ol><hr><h2 id="alur-menjalankan-tutup-buku-harian" tabindex="-1">Alur Menjalankan Tutup Buku Harian <a class="header-anchor" href="#alur-menjalankan-tutup-buku-harian" aria-label="Permalink to &quot;Alur Menjalankan Tutup Buku Harian&quot;">​</a></h2><p>Setiap sore hari setelah jam operasional sekolah selesai, kasir menjalankan proses tutup buku dengan alur berikut:</p>',14)),(n(),s(p,null,{default:i(()=>[k(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%221.%20Klik%20Tombol%20Tutup%20Buku%20Baru%22%5D%20--%3E%20B%5B%222.%20Pilih%20Rentang%20Tanggal%20Tutup%20Buku%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Sistem%20Kalkulasi%20Otomatis%20Penjualan%20dan%20Retur%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Buka%20Detail%20Slip%20dan%20Cek%20Hak%20Supplier%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20Serahkan%20Pembayaran%20dan%20Tandai%20Lunas%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%226.%20Cetak%20Slip%20Bukti%20Rekapitulasi%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="langkah-langkah" tabindex="-1">Langkah-langkah: <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah:&quot;">​</a></h3><ol><li>Klik tombol ungu <strong><code>+ Proses Tutup Buku Baru</code></strong> di pojok kanan atas.</li><li>Jendela modal formulir tutup buku akan terbuka: <ul><li><strong>Dari Tanggal &amp; Sampai Tanggal</strong>: Pilih rentang waktu transaksi yang ingin dihitung tutup bukunya (biasanya tanggal hari ini).</li><li><strong>Catatan Tutup Buku</strong>: Tulis keterangan pengingat (contoh: <em>Tutup buku sore hari jam 16.00</em>).</li></ul></li><li>Klik tombol <strong>Jalankan Tutup Buku</strong>.</li><li>Sistem seketika mengumpulkan seluruh transaksi POS pada periode tersebut, menghitung sisa barang retur yang tidak laku, memotong persentase komisi kantin, dan menerbitkan <strong>Nomor Settlement</strong> unik (misal: <code>SET-20261009-696</code>).</li></ol><hr><h2 id="memeriksa-rincian-per-pedagang-detail-slip" tabindex="-1">Memeriksa Rincian per Pedagang (Detail Slip) <a class="header-anchor" href="#memeriksa-rincian-per-pedagang-detail-slip" aria-label="Permalink to &quot;Memeriksa Rincian per Pedagang (Detail Slip)&quot;">​</a></h2><ol><li>Pada tabel daftar settlement, klik tombol <strong><code>Detail Slip</code></strong> di baris transaksi terkait.</li><li>Jendela modal rincian slip akan menampilkan data akuntansi per supplier: <ul><li><strong>Nama Supplier</strong>: Identitas pedagang mitra titip jual.</li><li><strong>Jumlah Titip Awal (<em>Initial Qty</em>)</strong>: Jumlah porsi makanan yang dibawa supplier di pagi hari.</li><li><strong>Jumlah Terjual (<em>Sold Qty</em>)</strong>: Jumlah porsi makanan yang berhasil laku terjual di kasir POS.</li><li><strong>Jumlah Retur (<em>Returned Qty</em>)</strong>: Jumlah makanan sisa yang dikembalikan ke supplier di sore hari.</li><li><strong>Omset Kotor (<em>Gross Revenue</em>)</strong>: Total pendapatan dari makanan supplier tersebut.</li><li><strong>Hak Bersih Supplier (<em>Net Payout</em>)</strong>: Nominal uang yang harus dibayarkan ke supplier setelah dipotong komisi kantin.</li></ul></li><li>Anda dapat menekan tombol <strong><code>Cetak Slip Rekapitulasi</code></strong> untuk mencetak bukti perhitungan fisik bagi pedagang saat menyerahkan uang hasil jualan.</li></ol><hr><h2 id="menandai-pelunasan-pembayaran-supplier" tabindex="-1">Menandai Pelunasan Pembayaran Supplier <a class="header-anchor" href="#menandai-pelunasan-pembayaran-supplier" aria-label="Permalink to &quot;Menandai Pelunasan Pembayaran Supplier&quot;">​</a></h2><p>Setelah uang hak supplier diserahkan secara tunai atau ditransfer melalui rekening bank:</p><h3 id="_1-pelunasan-satuan-per-transaksi" tabindex="-1">1. Pelunasan Satuan (Per Transaksi): <a class="header-anchor" href="#_1-pelunasan-satuan-per-transaksi" aria-label="Permalink to &quot;1. Pelunasan Satuan (Per Transaksi):&quot;">​</a></h3><ul><li>Klik tombol hijau <strong><code>Lunas</code></strong> pada baris nomor settlement yang ingin diselesaikan.</li><li>Jendela konfirmasi akan muncul. Masukkan catatan pembayaran (misal: <em>Ditransfer via BCA sore hari</em>), lalu klik <strong>Ya, Konfirmasi LUNAS</strong>.</li></ul><h3 id="_2-pelunasan-massal-bulk-action-bar" tabindex="-1">2. Pelunasan Massal (<em>Bulk Action Bar</em>): <a class="header-anchor" href="#_2-pelunasan-massal-bulk-action-bar" aria-label="Permalink to &quot;2. Pelunasan Massal (*Bulk Action Bar*):&quot;">​</a></h3><ul><li>Jika Anda ingin melunasi banyak rekapitulasi sekaligus di akhir pekan atau akhir bulan: <ol><li>Berikan tanda centang pada kotak di samping nomor-nomor settlement yang ingin dilunasi.</li><li>Bilah hijau <strong>Bulk Action Bar</strong> akan muncul di atas tabel.</li><li>Klik tombol <strong><code>Tandai Lunas Terpilih</code></strong>.</li><li>Masukkan catatan pelunasan dan konfirmasi.</li><li>Seluruh status settlement yang dipilih akan seketika berubah menjadi <strong>Lunas</strong>.</li></ol></li></ul>',12))])}const _=l(d,[["render",g]]);export{P as __pageData,_ as default};
